#!/usr/bin/env python3
"""One-off sync of the exercise_plan catalog to match what was pruned/
renamed via the Manage Exercises tab on dev, without touching
workout_log/exercise_log/users on whatever DB this runs against.

Run this ON THE SERVER the target DB lives on (e.g. a PythonAnywhere
Bash console, `cd` into the deployed repo) so it resolves the same
DB_PATH the running app itself uses (see db.py / config.py). It defaults
to a dry run - pass --apply to actually write.

    python scripts/sync_exercise_plan.py          # preview only
    python scripts/sync_exercise_plan.py --apply   # write the changes

exercise_plan has no uniqueness constraint, so a couple of exercises
intentionally have two rows with the same name (an artifact of the
free-exercise-db bulk import overlapping the original curated list) -
this is diffed as a multiset over the full row content (muscle,
exercise, type, images), not just (muscle, exercise), so those
legitimate duplicates are preserved rather than collapsed.
"""
import argparse
import json
import os
import sqlite3
import sys
from collections import Counter

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import db  # noqa: E402  (needs the sys.path tweak above)

