def row_key(target_muscle, exercise, ex_type, images):
    # curated is deliberately excluded from the match key - it's just a
    # picker-ordering hint, not part of "what exercise is this."
    return (target_muscle, exercise, ex_type, images)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--apply", action="store_true", help="write changes (default is dry-run preview)")
    args = parser.parse_args()

    print(f"Target DB: {db.DB_PATH}")
    conn = sqlite3.connect(db.DB_PATH)
    current = conn.execute("SELECT id, target_muscle, exercise, type, images FROM exercise_plan").fetchall()

    current_counter = Counter(row_key(r[1], r[2], r[3], r[4]) for r in current)
    desired_counter = Counter(row_key(d["target_muscle"], d["exercise"], d["type"], d["images"]) for d in DESIRED)

    # ids to delete: pick specific row ids for any key present in prod more
    # times than desired (covers full removal and partial over-count alike).
    ids_by_key = {}
    for r in current:
        ids_by_key.setdefault(row_key(r[1], r[2], r[3], r[4]), []).append(r[0])

    to_delete_ids = []
    for key, have in current_counter.items():
        want = desired_counter.get(key, 0)
        if have > want:
            to_delete_ids.extend(ids_by_key[key][: have - want])

    to_insert = []
    desired_by_key = {}
    for d in DESIRED:
        desired_by_key.setdefault(row_key(d["target_muscle"], d["exercise"], d["type"], d["images"]), []).append(d)
    for key, want in desired_counter.items():
        have = current_counter.get(key, 0)
        if want > have:
            to_insert.extend(desired_by_key[key][: want - have])

    print(f"Current exercise_plan rows: {len(current)}")
    print(f"Desired rows: {len(DESIRED)}")
    print(f"\nWill delete {len(to_delete_ids)} row(s):")
    id_to_row = {r[0]: r for r in current}
    for rid in to_delete_ids[:60]:
        r = id_to_row[rid]
        print(f"  - [{r[1]}] {r[2]}")
    if len(to_delete_ids) > 60:
        print(f"  ...and {len(to_delete_ids) - 60} more")

    print(f"\nWill insert {len(to_insert)} row(s):")
    for d in to_insert[:60]:
        print(f"  + [{d['target_muscle']}] {d['exercise']}")
    if len(to_insert) > 60:
        print(f"  ...and {len(to_insert) - 60} more")

    if not args.apply:
        print("\nDry run only - nothing was written. Re-run with --apply to write these changes.")
        conn.close()
        return

    conn.executemany("DELETE FROM exercise_plan WHERE id = ?", [(i,) for i in to_delete_ids])
    conn.executemany(
        "INSERT INTO exercise_plan (target_muscle, exercise, type, images, curated) VALUES (?, ?, ?, ?, ?)",
        [(d["target_muscle"], d["exercise"], d["type"], d["images"], d["curated"]) for d in to_insert],
    )
    conn.commit()
    conn.close()
    print(f"\nApplied: deleted {len(to_delete_ids)}, inserted {len(to_insert)}.")


if __name__ == "__main__":
    main()
